  auto rec = nlohmann::json::parse(kSnapshotJson);
  hanabi::Game game = hanabi::logging::apply_snapshot(rec);
  // On T1 yagami_black clued rank 1 to will-bot67, touching slot 5 alone.
  // With every stack on 0 the useful set was {r1, b1, o1} -- MIXED, plain and
  // inverted together -- and the old rule declared that undecidable and
  // declined the whole direct-play reading. The clue degraded to a bare
  // REVEAL that stamped nothing, so will-bot67 carried an unstamped playable 1
  // for six turns and threw its chop here on T8 instead.
  //
  // The mixed set is now a direct play clue: o1 is dropped from the
  // INFERENCES rather than killing the reading, slot 5 is stamped CTP, and it
  // gets played. Order 5 is that slot 5 card.
  hanabi::PerformAction action = game.take_action();
  ASSERT_TRUE(std::holds_alternative<hanabi::PerformPlay>(action))
      << "the clued 1 carries a standing play call and must be played";
  EXPECT_EQ(std::get<hanabi::PerformPlay>(action).target, 5);
